*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_searchText", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("searchText")))); } }];
