        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf73000.onpageload' });
    }
};


