/**
 * @method
 * @name scwin.tx_fn_searchRelLawDtl
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchRelLawDtl = async function () {
    const sbmOptions = {
        id: "tx_fn_searchRelLawDtl",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_searchRelLawDtlReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf73000.tx_fn_searchRelLawDtl" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_loadListReq",
        target: "dlt_junmoonList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf73000.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["pageCount"] != null ? rj["pageCount"] : (rj.body && rj.body["pageCount"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_53").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};


